HUB = ('Business and creator account help', '/business-and-creator-account-help/')
LEG = ('Your rights when an account is banned', '/your-rights-when-meta-disables-your-account/')
VER = ('Meta Verified and account support', '/meta-verified-support-how-to-use/')

page('instagram-business-account-disabled-lost-income', 'igsusp', 'Instagram Business Account Disabled: Protect Your Income',
 'Your Instagram business account is disabled and sales have stopped. What to do first, how to appeal, and how to keep customers in the meantime.',
 'Instagram business account disabled and it is your income?', 'Business account disabled, income at stake',
 'When the account is the shop window, every day offline costs you. Here is the order that protects the appeal and the business.',
 'If your Instagram business account is disabled, appeal once from the notice, with accurate details, before the appeal window closes. Do not open replacement accounts from the same phone, as linked accounts are often removed too. Tell customers through email, your website or another channel, and save every notice with its date.',
 [('Appeal once, properly', 'One accurate appeal beats five rushed ones.'), ('No replacement accounts', 'New accounts on the same device are often removed as well.'), ('Reach customers elsewhere', 'Email lists, your site and Google Business Profile still work.')],
 [S('The first 48 hours',
    ol(['Screenshot the notice, including the date and any appeal deadline shown.',
        'Log in from the phone you normally use and follow the appeal from the notice. Write in plain language what the business sells and why the decision looks wrong.',
        'If Instagram asks for ID or a video selfie, complete it once, in good light, with the name on your ID matching the account owner.',
        'Check Accounts Center. If the linked Facebook profile is also restricted, deal with that first, because it can block the Instagram appeal.',
        'Pause any ads running from the account in Ads Manager so you are not paying for traffic to a profile nobody can see.'])),
  S('Keeping the business running',
    'Post a short note on your website and email list saying the Instagram account is temporarily unavailable and how to order. Update the link on your Google Business Profile. If customers DM you for orders, give them a phone number or email they can use. None of this affects the appeal.'),
  S('What not to do',
    ul(['Do not create a new business account with the same email, phone or device. Instagram can treat it as an attempt to get around the decision.',
        'Do not pay anyone in your DMs who says they know someone at Meta. Nobody can buy a reinstatement.',
        'Do not delete posts in bulk. It does not lift a suspension and can remove evidence that the account was genuine.'])),
 ],
 [('How long do I have to appeal?', 'Instagram usually shows the deadline on the notice. Check what your notice says and act well before it ends.'),
  ('Will my followers be lost?', 'While the account is disabled it is hidden, not deleted. If the appeal succeeds, followers and posts usually come back with it.'),
  ('Can I run my shop from a new account meanwhile?', 'It is risky. A new account linked to the same person or device can be removed for the same reason. Use your other channels instead.')],
 ['Shops, salons, studios and service businesses whose Instagram account brings in orders.', 'Founders whose personal account and business account were disabled together.', 'Anyone in the US, UK, EU, Canada or Australia whose main sales channel just disappeared.'],
 area=None)

page('instagram-backup-account-also-suspended', 'igsusp', 'Backup Instagram Account Suspended Too: Why and What Now',
 'Your main Instagram was disabled, then your backup or new account went too. Why linked accounts get removed and what to do instead.',
 'Your backup Instagram account was suspended as well?', 'Backup account suspended too',
 'This is one of the most common things we hear. The new account is linked to the old one, so it inherits the problem.',
 'Instagram links accounts by device, phone number, email, payment details and Accounts Center. When one account is disabled, a new or backup account linked to it is often removed too, sometimes for circumventing the original decision. Stop creating accounts, appeal the main one and keep the evidence that it was genuine.',
 [('Stop opening accounts', 'Each new one can count against you.'), ('Appeal the original', 'That is the decision that matters.'), ('Keep proof', 'Screenshots, invoices and the notice dates help.')],
 [S('Why the backup went too',
    'Meta’s rules let it remove accounts created to get around an enforcement action. An account made on the same phone, with the same email or number, or added to the same Accounts Center, looks like that to an automated system even when you only wanted to keep in touch with customers.'),
  S('What to do now',
    ol(['Stop creating new accounts on the same device or details.',
        'Open each notice and note which account was removed for what reason. The original reason and the backup reason are often different.',
        'Appeal the original account first. If the backup notice offers its own appeal, use it and say plainly that it was created to keep your business reachable.',
        'If your linked Facebook profile is affected, check its status in Accounts Center.',
        'Save the dates of every notice and decision.'])),
  S('If you are in the EU or UK',
    'EU users can take a final Instagram decision to a certified out-of-court dispute body such as Appeals Centre Europe within six months. UK users can ask Meta for a copy of their personal data. See %s.' % A(LEG[1], 'your rights when an account is banned')),
 ],
 [('Will a new phone fix it?', 'Not on its own. Accounts are linked by more than the device, and using a new phone to open new accounts can still count as getting around the decision.'),
  ('Should I appeal the backup account too?', 'Yes, if the notice offers an appeal. Keep it short and honest about why the account exists.'),
  ('Can I ever open a new account?', 'If the original decision stands after review, the terms you agreed to may not allow a new account. Read the notice and Meta’s terms before you try.')],
 ['People whose second or replacement Instagram account was removed within hours or days.', 'Small businesses that opened a new profile to keep selling.', 'Creators who lost a main and a backup account in the same week.'])

page('instagram-business-account-disabled-ads-still-running', 'ad', 'Instagram Disabled but Ads Still Charging: What to Do',
 'Your Instagram account is disabled but ads linked to it may still be billing. How to check Ads Manager, pause spend and protect the ad account.',
 'Instagram account disabled, but your ads are still spending?', 'Disabled Instagram, ads still running',
 'Ads usually live in an ad account, not in the Instagram profile. That means you can often see and stop them from Ads Manager.',
 'If your Instagram account is disabled, open Meta Ads Manager from a Facebook profile or business portfolio that still has access to the ad account. Check which ads use the Instagram account as their identity, pause them, and download the billing history. Then appeal the Instagram account separately. The two decisions are reviewed apart.',
 [('Find the ad account', 'Ads are billed to an ad account, not to the profile.'), ('Pause what is live', 'Stop spend going to a profile people cannot open.'), ('Appeal separately', 'The Instagram and ad decisions are separate.')],
 [S('Check and pause',
    ol(['Log in to Ads Manager or Meta Business Suite from an admin profile that still works.',
        'Filter campaigns by the Instagram account they use as identity.',
        'Pause active campaigns and boosted posts that point to the disabled account.',
        'Download invoices from Billing and payments for your records.',
        'Check Account Quality to see whether the ad account itself is also restricted.'])),
  S('If you cannot reach Ads Manager',
    'If the only admin was the disabled account, or the linked Facebook profile is restricted too, you may not be able to pause anything. Contact your bank about the card only if charges look unauthorised, and be aware that chargebacks on Meta billing can lead to the ad account being restricted. See %s.' % A('/disabled-ad-account-unpaid-balance/', 'unpaid balance on a disabled ad account')),
 ],
 [('Do ads stop on their own when Instagram is disabled?', 'Not always. Ads can keep running with a Facebook Page identity, and some placements may still deliver. Check rather than assume.'),
  ('Will pausing ads hurt my appeal?', 'No. Pausing spend is a billing decision and does not affect the review of the Instagram account.'),
  ('Can someone else on the business portfolio pause them?', 'Yes. Any admin with the right access in the business portfolio can pause campaigns.')],
 ['Businesses with campaigns running when Instagram disabled the account.', 'Agencies managing ads for a client whose profile went down.', 'Owners who see charges and cannot find the ads.'])

page('brand-instagram-account-locked-after-employee-left', 'igrecov', 'Brand Instagram Locked After an Employee or Agency Left',
 'The person who set up your brand Instagram has left and you cannot log in. How to recover a company account the right way.',
 'Your brand Instagram is locked and the person who set it up has gone?', 'Brand account locked after staff left',
 'Ex-employees, freelancers and old agencies often hold the only login. Here is how companies get the account back without a fight.',
 'If an employee or agency who set up your brand Instagram has left, first ask them in writing to transfer the email, phone number and two-factor method to you. If they will not, use Instagram’s login help with the business email you control, and keep proof the brand is yours: registration, website, invoices.',
 [('Ask in writing', 'A clear, dated request is the first step.'), ('Use the business email', 'Recovery runs through the contact details on the account.'), ('Prove ownership', 'Company registration and domain help.')],
 [S('Start with the handover',
    ol(['Write to the former employee or agency asking them to change the email and phone on the account to ones the company controls, and to switch off their two-factor method.',
        'Ask them to remove their own Facebook profile from Accounts Center if the account is linked to it.',
        'If a business portfolio manages the account, check who is admin in Meta Business Settings.',
        'Agree a date and confirm in writing once it is done.'])),
  S('If they will not cooperate',
    'Try Instagram’s Forgot password from the login screen with any email or phone your company still controls. If none of the contact details are yours, Instagram may offer a video selfie only when your face appears in the posts, which a brand often cannot do. In that situation, an impersonation or intellectual property report is sometimes the only route. A solicitor or lawyer can also write to the person if the account was created for the company.'),
  S('Stop it happening again',
    ul(['Register brand accounts with a role email such as social@yourdomain, not a personal address.',
        'Put the account in a business portfolio with at least two company admins.',
        'Use an authenticator app held by the company, and keep recovery codes in a password manager.'])),
 ],
 [('Can Instagram give the account to my company?', 'Instagram does not transfer accounts on request. Recovery works through the account’s own email, phone and verification steps, or through reports where the brand is being used without permission.'),
  ('Does a trademark help?', 'It helps if the account is being used to impersonate the brand or the handle is needed for a trademark claim. It does not unlock an account on its own.'),
  ('The agency is holding the account until we pay. What now?', 'Keep the request and their reply in writing and get legal advice. Do not share any further access with them.')],
 ['Brands whose social media manager has left the company.', 'Businesses that changed agency and lost the login.', 'Founders who set up the account years ago with an old email.'])

page('facebook-profile-disabled-managing-business-pages', 'fbdis', 'Facebook Profile Disabled and You Manage Business Pages',
 'Your personal Facebook profile is disabled and with it you lost the Pages, business portfolio and ad accounts you manage. What to do first.',
 'Your Facebook profile is disabled and it was the admin of your business Pages?', 'Profile disabled, Pages lost',
 'On Facebook, Pages and ad accounts are managed through a personal profile. When that profile goes, access to everything it manages goes with it.',
 'When a personal Facebook profile is disabled, you lose access to every Page, business portfolio and ad account it manages. Appeal the profile first. Meanwhile, ask any other admin to keep the Pages running, and check whether the business portfolio has a second admin. If nobody else has access, the profile appeal is the main route back.',
 [('Appeal the profile', 'Everything depends on it.'), ('Ask other admins', 'They can keep Pages and ads running.'), ('Plan a backup admin', 'Two admins protect the business next time.')],
 [S('What still works',
    'The Pages themselves usually stay online. Other admins of the Page or business portfolio keep their access. Ads can keep delivering until someone with access pauses them. What you lose is your own ability to manage them.'),
  S('Steps to take',
    ol(['Open the notice on facebook.com and follow the appeal. Confirm your identity if asked, using ID with the name on the profile.',
        'List every Page, business portfolio and ad account you managed.',
        'Contact any other admin and ask them to check access and pause ads if needed.',
        'If you were the only admin, keep the business details ready: registration, domain email, invoices.',
        'Once the profile is back, add a second trusted admin to everything.'])),
  S('Agencies and freelancers',
    'If the disabled profile belonged to someone at an agency, the client can usually add a different person to the business portfolio from their own side. See %s.' % A('/agency-ad-account-recovery/', 'agency ad account recovery')),
 ],
 [('Will my Pages be deleted?', 'Not because your profile is disabled. Pages stay up unless they have their own restriction.'),
  ('Can I make a new profile to manage the Pages?', 'Creating a new profile while your account is disabled can go against Meta’s terms and lead to that profile being disabled too.'),
  ('Can Meta add a new admin to my Page?', 'In some situations Meta offers a Page access request for businesses that can prove they own the Page. It is not available for every Page.')],
 ['Business owners whose personal profile managed their Pages and ads.', 'Social media managers who look after several brands.', 'Agencies whose staff profile was disabled.'])

page('instagram-monetisation-restricted-creator', 'igrestrict', 'Instagram Monetisation Restricted: What Creators Can Do',
 'Instagram says your account is not eligible to monetise or a feature was removed. How to read Monetization status and what you can appeal.',
 'Instagram says you can no longer earn from your account?', 'Monetisation restricted',
 'Monetisation status sits apart from account status. Your account can be fine while earnings tools are switched off.',
 'Instagram can remove monetisation tools such as subscriptions, gifts, bonuses or branded content when an account or its content breaks Meta’s monetisation policies. Open Professional dashboard, then Monetization status, to see which policy and which content is involved. Fix or remove what is listed, and request a review where the option appears.',
 [('Check Monetization status', 'It lists the policy and the content.'), ('Fix what is listed', 'Remove or edit the flagged posts.'), ('Request a review', 'Where the button is shown.')],
 [S('Where to look',
    'In the Instagram app go to your profile, Professional dashboard, then Monetization status. It shows whether the account is eligible and which policy was broken. Account status, under Settings, shows separate community guideline issues. Both can affect what you earn.'),
  S('Common reasons',
    ul(['Content that breaks Meta’s content monetisation policies, such as unoriginal or recycled content.',
        'Undisclosed paid partnerships. Branded content needs the paid partnership label.',
        'Recent community guideline violations on the account.',
        'Living in a country where a feature is not available.'])),
  S('What to do',
    ol(['Read the exact policy and post listed.', 'Remove or edit the content if it is yours to fix.', 'Request a review if the option is shown, once.',
        'Keep posting original content within the rules. Eligibility can come back once the issue has passed.'])),
 ],
 [('Is my account going to be disabled?', 'Not necessarily. A monetisation restriction is separate from account suspension, though repeated violations can lead to both.'),
  ('Do I lose money already earned?', 'Payouts follow the terms of each programme. Check the payout section of Professional dashboard.'),
  ('Can I appeal if there is no button?', 'If no review option is shown, the usual route is to fix the issue and wait for eligibility to be checked again.')],
 ['Creators who earn from subscriptions, gifts or branded content.', 'Influencers who lost access to paid partnership tools.', 'Talent managers looking after a creator’s account.'])

page('instagram-shopping-commerce-account-restricted', 'igrestrict', 'Instagram Shopping Restricted or Shop Rejected: Next Steps',
 'Instagram Shopping or your shop was rejected or restricted. How to check commerce eligibility in Commerce Manager and request a review.',
 'Your Instagram shop was rejected or shopping was switched off?', 'Shopping or shop restricted',
 'Shop features follow Meta’s commerce eligibility rules and commerce policies, which are stricter than the rules for posting.',
 'If Instagram Shopping is rejected or restricted, open Commerce Manager and check the shop or catalogue status. Meta lists the reason, such as domain, product type or commerce policy. Fix the listed issue, for example verify your domain or remove restricted products, then request a review from the same screen where the option appears.',
 [('Open Commerce Manager', 'It shows the shop status.'), ('Fix the listed issue', 'Domain, products or policy.'), ('Request a review', 'From the same screen.')],
 [S('Common reasons',
    ul(['The website domain is not verified or does not show the products and their details.', 'The shop sells products Meta restricts, such as some health products or weapons accessories.',
        'The account is new or has little activity.', 'The business is in a market where Shops are not available.'])),
  S('Steps', ol(['In Commerce Manager, open the shop and read the status and reason.', 'Verify your domain in Business Settings if asked.',
        'Remove products that break the commerce policies from the catalogue.', 'Request a review and keep a note of the date.'])),
 ],
 [('Does a shop rejection affect my account?', 'The shop decision is separate, but repeated commerce violations can lead to wider restrictions.'),
  ('Can I still tag products?', 'Not while shopping is restricted. You can still link to your site in your bio.'),
  ('How do I verify my domain?', 'In Meta Business Settings under Brand safety, Domains. See %s.' % 'our domain verification guide')],
 ['Online stores selling through Instagram.', 'Brands whose catalogue was rejected.', 'Ecommerce agencies setting up shops for clients.'])
